public String issue(String username, java.util.List<String> roles) {
    Date now = new Date();
    return Jwts.builder()
        .__1__(username)                                  // 主题：用户名
        .claim("roles", roles)
        .expiration(new Date(now.getTime() + expireMs))   // 必须设置：否则 Token 永不过期
        .signWith(key)                                    // __2__ 防篡改
        .compact();
}

private Claims parse(String token) {
    // 解析即验签：签名不符或过期抛异常
    return Jwts.parser().verifyWith(key).build().__3__(token).getPayload();
}
